  'admin.oauth.schoolItChecklist': 'ລາຍການກວດສອບ IT DingTalk:\n1. ເປີດໃຊ້ "ເຂົ້າສູ່ລະບົບເວັບໄຊທ໌ຂອງພາກສ່ວນທີສາມ/ສະແກນລະຫັດ QR ເພື່ອເຂົ້າສູ່ລະບົບ"\n2. ໃສ່ URL ໂທກັບ DingTalk ໃນການຕັ້ງຄ່າ "ເຂົ້າສູ່ລະບົບ ແລະແບ່ງປັນ DingTalk" (ຕ້ອງຄືກັນແທ້)\n3. ສະຫມັກຂໍອະນຸຍາດສ່ວນບຸກຄົນ: permission-open_app_api_base, Contact.User.Read\n4. ໃຫ້ AppKey, AppSecret, CorpId (ທາງເລືອກ) ໃຫ້ກັບຜູ້ເບິ່ງແຍງລະບົບ MindGraph',
