  'admin.roleControlDescManagers': 'ຄຸ້ມຄອງຜູ້ບໍລິຫານໂຮງຮຽນ. ຜູ້ບໍລິຫານໂຮງຮຽນສາມາດເຂົ້າເຖິງ dashboard ຂອງໂຮງຮຽນສໍາລັບອົງການຈັດຕັ້ງຂອງເຂົາເຈົ້າ. ຜູ້​ໃຊ້​ຕ້ອງ​ໄດ້​ເຂົ້າ​ຮ່ວມ​ໂຮງ​ຮຽນ​ກ່ອນ​ທີ່​ຈະ​ໄດ້​ຮັບ​ການ​ອະ​ນຸ​ຍາດ​ໃຫ້​ບົດ​ບາດ​ນີ້​.',
