  'admin.schoolFeatureUsage.bottleneckNone': 'ອັດຕາການຜ່ານຂອງແຕ່ລະຂະບວນການທຸລະກິດໃນປີນີ້ແມ່ນມີຄວາມຫມັ້ນຄົງໂດຍລວມ, ແລະການຕອບສະຫນອງຂອງ LLM ແມ່ນບໍ່ແນ່ນອນຊ້າ (ມັນຕ້ອງສູງກວ່າຄ່າສະເລ່ຍແລະບັນລຸເປົ້າຫມາຍຂອງໂມດູນນີ້: 8 ວິນາທີສໍາລັບຜ້າໃບແລະ 90 ວິນາທີສໍາລັບການສົນທະນາ). ອັດຕາການຜ່ານຂະບວນການແມ່ນມາຈາກເຫດການທີ່ເປັນປະໂຫຍດ, ແລະອັດຕາການລົ້ມເຫຼວຂອງ LLM ແມ່ນມາຈາກການນໍາໃຊ້ token.',
  'admin.schoolFeatureUsage.bottleneckVolume': 'ອັດຕາການຜ່ານຂອງແຕ່ລະຂະບວນການໂດຍທົ່ວໄປແມ່ນສູງ. ຂໍ້ຈໍາກັດໃນປະຈຸບັນສ່ວນໃຫຍ່ແມ່ນມາຈາກການແຈກຢາຍການນໍາໃຊ້ແລະໂມດູນທີ່ບໍ່ມີປະໂຫຍດ ({idle}), ແທນທີ່ຈະເປັນການປະມວນຜົນລົ້ມເຫລວຫຼືຊ້າ.',
  'admin.schoolFeatureUsage.bottleneckSlow': 'ອັດຕາການຜ່ານແມ່ນມີຄວາມຫມັ້ນຄົງໂດຍລວມ. ຂະບວນການທີ່ມີການຕອບສະໜອງ LLM ສູງກວ່າຄ່າປານກາງທີ່ກົງກັບເກນຂອງໂມດູນນີ້ແມ່ນ {slow}.',
  'admin.schoolFeatureUsage.bottleneckPass': 'ຂະບວນການທີ່ມີອັດຕາການຜ່ານຕ່ໍາແມ່ນ {lowest}; ຂະບວນການທີ່ມີການປະເມີນການໂຫຼດແຫນ້ນແມ່ນ {tense}. ອັດຕາການຜ່ານແມ່ນມາຈາກເຫດການທີ່ເປັນປະໂຫຍດ, ກະລຸນາຕີຄວາມມັນໂດຍອີງໃສ່ການນໍາໃຊ້.',
  'admin.schoolFeatureUsage.bottleneckPassSlow': 'ຂະບວນການທີ່ມີອັດຕາການຜ່ານຕ່ໍາແມ່ນ {lowest}; ຂະບວນການທີ່ມີການປະເມີນການໂຫຼດທີ່ເຄັ່ງຄັດແມ່ນ {tense}; ຂະບວນການທີ່ມີການຕອບສະໜອງ LLM ຊ້າ (ສູງກວ່າຄ່າປານກາງ ແລະເຖິງເກນໂມດູນ) ແມ່ນ {slow}.',
