  'admin.schoolFeatureUsage.lowIdleBody': 'ຄວາມຖີ່ຕໍ່າ: {low}. idle ໃນໄລຍະຍາວ: {idle}. ຂໍ້​ມູນ​ທີ່​ບໍ່​ໄດ້​ໃຊ້​ງານ​ອາດ​ຈະ​ປະ​ກອບ​ມີ​ຫນ້າ​ທີ່​ບໍ່​ໄດ້​ເປີດ​ໂດຍ​ໂຮງ​ຮຽນ​.',
  'admin.schoolFeatureUsage.conclusionTitle': '4. ການຄົ້ນຄວ້າທີ່ສົມບູນແບບແລະການຕັດສິນກ່ຽວກັບການນໍາໃຊ້ຫນ້າທີ່',
  'admin.schoolFeatureUsage.conclusionConcentrated': 'ການນໍາໃຊ້ແມ່ນສຸມໃສ່ {top}. ໂມດູນທີ່ບໍ່ໄດ້ເຮັດວຽກ ຫຼືບໍ່ໄດ້ສ້າງເຫດການອອກແມ່ນ {idle}. ການ​ນໍາ​ໃຊ້​ແມ່ນ​ສຸມ​ໃສ່​ການ​ບາງ​ຫນ້າ​ທີ່​ຫຼັກ​, ແລະ​ລາຍ​ການ​ທີ່​ບໍ່​ໄດ້​ເຮັດ​ວຽກ​ອາດ​ຈະ​ປະ​ກອບ​ມີ​ຫນ້າ​ທີ່​ບໍ່​ໄດ້​ເປີດ​ໃຊ້​ງານ​.',
  'admin.schoolFeatureUsage.conclusionSpread': 'ການນໍາໃຊ້ແມ່ນຂ້ອນຂ້າງກະແຈກກະຈາຍ, ແລະໂມດູນເທິງແມ່ນ {top}. ໂມດູນທີ່ບໍ່ໄດ້ເຮັດວຽກ ຫຼືບໍ່ໄດ້ສ້າງເຫດການອອກແມ່ນ {idle}. ລາຍການທີ່ບໍ່ເຮັດວຽກອາດມີຟັງຊັນທີ່ບໍ່ໄດ້ເປີດໃຊ້.',
