  'admin.shareInviteMessage': '{orgName}: ຍິນ​ດີ​ຕ້ອນ​ຮັບ​ກັບ​ປະ​ສົບ​ການ​ການ​ສອນ​ການ​ຄິດ​ຄິດ​ຈິດ​ໃຈ​ແລະ​ເວ​ທີ​ການ​ຕົວ​ແທນ​ການ​ຄົ້ນ​ຄວ້າ​! \nສູນ​ຝຶກ​ອົບ​ຮົມ​ແນວ​ຄິດ​ຂອງ​ມະ​ຫາ​ວິ​ທະ​ຍາ​ໄລ​ປົກ​ກະ​ຕິ​ປັກ​ກິ່ງ​ຊີ້​ນໍາ​ການ​ຄົ້ນ​ຄວ້າ​ແລະ​ການ​ພັດ​ທະ​ນາ​, ແລະ​ໄດ້​ຮັບ​ການ​ຮ່ວມ​ມື​ໂດຍ​ຫຼາຍ​ກວ່າ​ຮ້ອຍ​ໂຮງ​ຮຽນ​ພັນ​ທະ​ມິດ​ການ​ພັດ​ທະ​ນາ​ແນວ​ຄິດ​. ທ່ານໄດ້ຖືກເຊື້ອເຊີນໃຫ້ເຂົ້າຮ່ວມກັບເພື່ອນມິດຂອງທ່ານໃນການຄົ້ນຄວ້າຮ່ວມກັນແລະປັບປຸງຄວາມສາມາດໃນການຄິດຂອງທ່ານໃນຍຸກ AI! \nວິທີ: ເປີດຄອມພິວເຕີ ຫຼື ໂທລະສັບມືຖື, ໃຊ້ເບີໂທລະສັບມືຖື + ລະຫັດເຊີນເພື່ອເຮັດສໍາເລັດການລົງທະບຽນຄັ້ງທໍາອິດ, ແລ້ວເຂົ້າສູ່ລະບົບດ້ວຍລະຫັດຢືນຢັນໂທລະສັບມືຖື.\nເວັບໄຊທ໌: {siteUrl}\nລະຫັດເຊີນສະເພາະອົງການ: {code}',
